package com.matthayesego.duckforcetoolkit;

import android.app.Activity;
import android.content.Intent;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;

/** Thin wrappers keep proven feature logic intact while applying the active TornFCA visual system. */
public final class TornFcaScreens {
    private TornFcaScreens(){}
    private static void brand(Activity a){ViewGroup root=a.findViewById(android.R.id.content);if(root!=null){if(BuildConfig.APPLICATION_ID.endsWith(".beta"))BetaSurfacePolish.apply(a,root);else TornFcaBrand.apply(a,root);}}
    private static void brand(Activity a,View v){brand(a);}
    private static Intent route(Activity a,Intent i){return TornFcaBrand.retarget(a,i);}
    private static int dp(Activity a,int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}

    private static void addWarSimulationCard(Activity a,View root){if(!(root instanceof ScrollView))return;ScrollView scroll=(ScrollView)root;if(scroll.getChildCount()==0||!(scroll.getChildAt(0) instanceof LinearLayout))return;LinearLayout page=(LinearLayout)scroll.getChildAt(0);for(int i=0;i<page.getChildCount();i++)if("tornfca-war-simulation".equals(page.getChildAt(i).getTag()))return;boolean enabled=DeveloperSettings.simulateWar(a);LinearLayout card=new LinearLayout(a);card.setTag("tornfca-war-simulation");card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(a,16),dp(a,15),dp(a,16),dp(a,15));GradientDrawable bg=new GradientDrawable();bg.setColor(Color.rgb(20,27,38));bg.setCornerRadius(dp(a,17));bg.setStroke(dp(a,1),enabled?Color.rgb(63,185,80):Color.rgb(243,184,52));card.setBackground(bg);TextView title=new TextView(a);title.setText("War wall simulation");title.setTextColor(Color.rgb(245,248,252));title.setTextSize(18);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);card.addView(title);TextView body=new TextView(a);body.setText(enabled?"ON — TornFCA will present a clearly marked upcoming ranked war so the gated War Center tools can be tested. No Torn data is changed.":"OFF — War Center uses Torn's real ranked-war state and keeps opponent tools hidden unless a war is scheduled or live.");body.setTextColor(Color.rgb(151,163,179));body.setTextSize(13);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);bp.topMargin=dp(a,6);card.addView(body,bp);Button toggle=new Button(a);toggle.setText(enabled?"Turn Simulated War Off":"Turn Simulated War On");toggle.setAllCaps(false);toggle.setTextColor(Color.rgb(245,248,252));toggle.setTypeface(Typeface.DEFAULT,Typeface.BOLD);GradientDrawable tb=new GradientDrawable();tb.setColor(Color.rgb(27,36,49));tb.setCornerRadius(dp(a,11));tb.setStroke(dp(a,1),enabled?Color.rgb(63,185,80):Color.rgb(243,184,52));toggle.setBackground(tb);toggle.setOnClickListener(v->{DeveloperSettings.setSimulateWar(a,!DeveloperSettings.simulateWar(a));a.recreate();});LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(a,46));tp.topMargin=dp(a,9);card.addView(toggle,tp);if(enabled){Button open=new Button(a);open.setText("Open Simulated War Center");open.setAllCaps(false);open.setTextColor(Color.rgb(245,248,252));open.setTypeface(Typeface.DEFAULT,Typeface.BOLD);GradientDrawable ob=new GradientDrawable();ob.setColor(Color.rgb(27,36,49));ob.setCornerRadius(dp(a,11));ob.setStroke(dp(a,1),Color.rgb(88,166,255));open.setBackground(ob);open.setOnClickListener(v->{Intent i=new Intent(a,WarCenter.class);i.putExtra(FactionOpsActivity.EXTRA_FACTION_ID,a.getIntent().getIntExtra(DeveloperConsoleActivity.EXTRA_FACTION_ID,0));i.putExtra(FactionOpsActivity.EXTRA_FACTION_NAME,a.getIntent().getStringExtra(DeveloperConsoleActivity.EXTRA_FACTION_NAME));i.putExtra(FactionOpsActivity.EXTRA_FACTION_API,a.getIntent().getBooleanExtra(DeveloperConsoleActivity.EXTRA_FACTION_API,false));i.putExtra(DeveloperConsoleActivity.EXTRA_POSITION,a.getIntent().getStringExtra(DeveloperConsoleActivity.EXTRA_POSITION));a.startActivity(i);});LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(a,46));op.topMargin=dp(a,7);card.addView(open,op);}LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);cp.topMargin=dp(a,4);cp.bottomMargin=dp(a,10);int index=Math.min(4,page.getChildCount());page.addView(card,index,cp);}

    public static class More extends MoreActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class About extends AboutActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class FeatureRouter extends FeatureRouterActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class WarCenter extends WarCenterActivity { @Override public void setContentView(View v){DeveloperSettings.simulateWar(this);super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class WarPayout extends WarPayoutActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class BankingCompanion extends BankingCompanionActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class MemberDossier extends MemberDossierActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class DeveloperGate extends DeveloperGateActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class DeveloperPanel extends DeveloperPanelActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class PremiumAdmin extends PremiumAdminActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class LeadershipAttention extends LeadershipAttentionActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class FactionStrength extends FactionStrengthActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class MemberFaction extends MemberFactionActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class WarNotice extends WarNoticeActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class FactionOps extends FactionOpsActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class OcTracker extends OcTrackerActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class QuickIntel extends QuickIntelActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class PremiumPreview extends PremiumPreviewActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
    public static class DeveloperConsole extends DeveloperConsoleActivity { @Override public void setContentView(View v){super.setContentView(v);brand(this,v);addWarSimulationCard(this,v);} @Override public void startActivity(Intent i){super.startActivity(route(this,i));} }
}
